-- inventory.zip_centroids seed — part 5 of the US ZIP centroid
-- lookup. See 20260901_zip_centroids_01.sql for the full source/license
-- note and RLS policy. This DDL is repeated (all IF NOT EXISTS / safe to
-- re-run) so each part file can be run standalone, in any order.
CREATE TABLE IF NOT EXISTS inventory.zip_centroids (
  zip    text PRIMARY KEY,
  city   text,
  state  text,
  county text,
  lat    numeric NOT NULL,
  lng    numeric NOT NULL
);
ALTER TABLE inventory.zip_centroids ENABLE ROW LEVEL SECURITY;
DROP POLICY IF EXISTS "zip_centroids_select" ON inventory.zip_centroids;
CREATE POLICY "zip_centroids_select" ON inventory.zip_centroids FOR SELECT
  USING (auth.role() = 'authenticated');

